ALTER TABLE installations
  ADD COLUMN IF NOT EXISTS coordinate_datum text NOT NULL DEFAULT 'WGS84',
  ADD COLUMN IF NOT EXISTS positional_uncertainty_m double precision,
  ADD COLUMN IF NOT EXISTS provenance text NOT NULL DEFAULT 'PUBLIC_REFERENCE',
  ADD COLUMN IF NOT EXISTS review_state text NOT NULL DEFAULT 'UNVERIFIED';

CREATE TABLE IF NOT EXISTS installation_runways (
  id text PRIMARY KEY,
  installation_id text NOT NULL REFERENCES installations(id),
  source_runway_id text NOT NULL,
  source_airport_ident text NOT NULL,
  designator text NOT NULL,
  true_heading_deg double precision,
  reciprocal_true_heading_deg double precision,
  length_m double precision,
  width_m double precision,
  surface text,
  closed_in_source boolean NOT NULL,
  centreline geometry(LineString,4326),
  threshold_elevations_msl_m jsonb,
  horizontal_datum text NOT NULL,
  vertical_datum text NOT NULL,
  positional_uncertainty_m double precision,
  provenance text NOT NULL,
  review_state text NOT NULL,
  mission_start_eligibility text NOT NULL,
  limitation text NOT NULL,
  content_hash text NOT NULL CHECK (content_hash ~ '^sha256:[0-9a-f]{64}$')
);

CREATE INDEX IF NOT EXISTS installation_runways_centreline_gix
  ON installation_runways USING gist(centreline);
CREATE INDEX IF NOT EXISTS installation_runways_installation_idx
  ON installation_runways(installation_id);

CREATE TABLE IF NOT EXISTS environment_packs (
  id text NOT NULL,
  version text NOT NULL,
  digest text NOT NULL CHECK (digest ~ '^sha256:[0-9a-f]{64}$'),
  schema_version text NOT NULL,
  study_area_id text NOT NULL REFERENCES study_areas(id),
  weather_preset_id text NOT NULL,
  intended_use text NOT NULL,
  provenance text NOT NULL,
  coverage geometry(Polygon,4326) NOT NULL,
  horizontal_datum text NOT NULL,
  vertical_datum text NOT NULL,
  source_vertical_datum text NOT NULL,
  valid_from timestamptz NOT NULL,
  valid_until timestamptz NOT NULL,
  terrain_digest text NOT NULL CHECK (terrain_digest ~ '^sha256:[0-9a-f]{64}$'),
  atmosphere_digest text NOT NULL CHECK (atmosphere_digest ~ '^sha256:[0-9a-f]{64}$'),
  installation_catalogue_digest text NOT NULL CHECK (installation_catalogue_digest ~ '^sha256:[0-9a-f]{64}$'),
  payload jsonb NOT NULL,
  superseded_at timestamptz,
  PRIMARY KEY (id, version, digest),
  UNIQUE (study_area_id, weather_preset_id, version)
);

CREATE INDEX IF NOT EXISTS environment_packs_coverage_gix
  ON environment_packs USING gist(coverage);

CREATE OR REPLACE FUNCTION reject_immutable_environment_update()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.payload IS DISTINCT FROM OLD.payload
     OR NEW.digest IS DISTINCT FROM OLD.digest
     OR NEW.terrain_digest IS DISTINCT FROM OLD.terrain_digest
     OR NEW.atmosphere_digest IS DISTINCT FROM OLD.atmosphere_digest
     OR NEW.installation_catalogue_digest IS DISTINCT FROM OLD.installation_catalogue_digest THEN
    RAISE EXCEPTION 'environment pack content is immutable; insert a new version';
  END IF;
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS environment_packs_immutable_content ON environment_packs;
CREATE TRIGGER environment_packs_immutable_content
BEFORE UPDATE ON environment_packs
FOR EACH ROW EXECUTE FUNCTION reject_immutable_environment_update();

